 const roomName=$('roomNameEdit');if(roomName)roomName.onchange=()=>transact(()=>{const r=selectedRecord();if(!r||app.selected?.kind!=='room')return;r.name=roomName.value.trim().slice(0,60)||'Untitled room';});
