const dx=p.x-d.p.x,dy=p.y-d.p.y;if(d.mode==='shape'){const g=app.engine.ground(p);if(g){d.end=[snap(g.x),snap(g.z)];engineDraw();}return;}if(d.mode==='move'){const rec=({item:app.plan.items,wall:app.plan.walls}[d.kind]||[]).find(x=>x.id===d.id);const g=app.engine.ground(p);if(rec&&g){dragPoint(rec,g,d);app.sceneCache=null;if(d.kind==='item'&&rec.group){app.engine.rebuild();}else app.engine.transform(d.kind,d.id,rec);engineDraw();updateMini();updateSelectionBubble();}return;}
