function key(e){if(e.target.closest('input,select,textarea,button,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(e.key.toLowerCase()==='q'){e.preventDefault();rotateSelection(-15);}else if(e.key.toLowerCase()==='e'){e.preventDefault();rotateSelection(15);}else if((e.key==='Delete'||e.key==='Backspace')&&selectedRecord()){e.preventDefault();act('delete');}else if(e.key.toLowerCase()==='f'){e.preventDefault();focusRoom('all');}else if(e.key==='Escape'){app.addingWall=null;app.shapeDraft=null;if(app.tool==='shape')setTool('build');else clearSelect();closeModal();}}
function minimapTransform(w=mini.width,h=mini.height){const px=app.plan.rooms.flatMap(r=>[r.x,r.x+r.w]),pz=app.plan.rooms.flatMap(r=>[r.z,r.z+r.d]);for(const wa of app.plan.walls){px.push(wa.a[0],wa.b[0]);pz.push(wa.a[1],wa.b[1]);}for(const it of app.plan.items){px.push(it.x);pz.push(it.z);}const minX=Math.min(0,...px),maxX=Math.max(8.7,...px),minZ=Math.min(0,...pz),maxZ=Math.max(8.3,...pz),pad=16,ratio=Math.min((w-2*pad)/Math.max(.5,maxX-minX),(h-2*pad)/Math.max(.5,maxZ-minZ));return{ratio,x:(w-(maxX-minX)*ratio)/2-minX*ratio,z:(h-(maxZ-minZ)*ratio)/2-minZ*ratio};}
function updateMini(){const w=mini.width,h=mini.height,ctx=miniCtx;ctx.clearRect(0,0,w,h);ctx.fillStyle='#101d19';ctx.fillRect(0,0,w,h);const {ratio,x,z}=minimapTransform(w,h);app.plan.rooms.forEach(r=>{ctx.fillStyle=r.id===app.focus?'#c8dfd1':'#33473f';ctx.beginPath();const points=polygonForShape(r.shape||'rectangle',r.x,r.z,r.x+r.w,r.z+r.d);points.forEach((p,i)=>{if(i===0)ctx.moveTo(x+p[0]*ratio,z+p[1]*ratio);else ctx.lineTo(x+p[0]*ratio,z+p[1]*ratio)});ctx.closePath();ctx.fill();ctx.strokeStyle='#597567';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#dce9dd';ctx.font='bold 15px system-ui';ctx.fillText(r.name.split(' ')[0],x+r.x*ratio+8,z+r.z*ratio+20);});if(app.plan.view.walls){ctx.strokeStyle='#e2bf7e';ctx.lineWidth=3;app.plan.walls.forEach(wa=>{ctx.beginPath();ctx.moveTo(x+wa.a[0]*ratio,z+wa.a[1]*ratio);ctx.lineTo(x+wa.b[0]*ratio,z+wa.b[1]*ratio);ctx.stroke();});}const overlap=collisions(app.plan);app.plan.items.filter(it=>!it.hidden&&app.plan.studio?.furnishings!==false).forEach(it=>{const sp=itemSpec(it),cx=x+it.x*ratio,cz=z+it.z*ratio;ctx.save();ctx.translate(cx,cz);ctx.rotate(it.r*Math.PI/180);ctx.fillStyle=app.selected?.id===it.id?'#6fe6e0':overlap.has(it.id)?'#e18a78':sp.color;ctx.fillRect(-sp.w*ratio/2,-sp.d*ratio/2,sp.w*ratio,sp.d*ratio);ctx.restore();});app.plan.fixtures.forEach(o=>{const wa=app.plan.walls.find(w=>w.id===o.wall);if(!wa)return;const p=wallPoint(wa,o.at);ctx.fillStyle=o.type==='window'?'#8cc8d3':o.type==='outlet'?'#edcda0':'#ffbe72';ctx.beginPath();ctx.arc(x+p[0]*ratio,z+p[1]*ratio,o.type==='outlet'?2:4,0,Math.PI*2);ctx.fill();});if(window.homePlanStudioDrawMini)window.homePlanStudioDrawMini(ctx,{x,z,ratio,w,h});}
function focusFromMini(e){const r=mini.getBoundingClientRect(),px=(e.clientX-r.left)*mini.width/r.width,pz=(e.clientY-r.top)*mini.height/r.height,w=mini.width,h=mini.height,transform=minimapTransform(w,h),ratio=transform.ratio,x=transform.x,z=transform.z,X=(px-x)/ratio,Z=(pz-z)/ratio,room=app.plan.rooms.find(v=>X>=v.x&&X<=v.x+v.w&&Z>=v.z&&Z<=v.z+v.d);if(room){focusRoom(room.id);if(app.tool==='build'){select('room',room.id);}else say('Focused '+room.name);}}
function download(name,contents,mime){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([contents],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportJSON(){download('home-plan-layout.json',JSON.stringify(app.plan,null,2),'application/json');say('Layout exported as JSON');}
function xmlEscape(s){return safe(s);}
function exportSVG(){const s=75,pad=40,coords=(x,z)=>[x*s+pad,z*s+pad],rect=(r)=>`<polygon points="${polygonForShape(r.shape||'rectangle',r.x,r.z,r.x+r.w,r.z+r.d).map(p=>`${p[0]*s+pad},${p[1]*s+pad}`).join(' ')}" fill="${r.color}" stroke="#758c82" stroke-width="1"/>`;const xs=[...app.plan.rooms.flatMap(r=>[r.x,r.x+r.w]),...app.plan.walls.flatMap(w=>[w.a[0],w.b[0]]),...app.plan.items.map(i=>i.x)],zs=[...app.plan.rooms.flatMap(r=>[r.z,r.z+r.d]),...app.plan.walls.flatMap(w=>[w.a[1],w.b[1]]),...app.plan.items.map(i=>i.z)];const minX=Math.min(...xs,0)*s-pad,maxX=Math.max(...xs,8.7)*s+pad,minZ=Math.min(...zs,0)*s-pad,maxZ=Math.max(...zs,8.3)*s+pad;let content=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${minX} ${minZ} ${maxX-minX} ${maxZ-minZ}" width="1500" height="1430"><rect width="100%" height="100%" fill="#f7f5eb"/><text x="38" y="28" fill="#29413b" font-family="sans-serif" font-size="15" font-weight="bold">HOME PLAN / PROVISIONAL SCHEMATIC — NOT MEASURED</text>`;app.plan.rooms.forEach(r=>content+=rect(r)+`<text x="${r.x*s+pad+8}" y="${r.z*s+pad+20}" fill="#344b44" font-family="sans-serif" font-size="13">${xmlEscape(r.name)}</text>`);app.plan.walls.forEach(wa=>{const a=coords(...wa.a),b=coords(...wa.b);content+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="#3e4a45" stroke-width="${wa.thick*s}" stroke-linecap="square"/>`;});app.plan.fixtures.forEach(f=>{const w=app.plan.walls.find(w=>w.id===f.wall);if(!w)return;const p=coords(...wallPoint(w,f.at));content+=`<circle cx="${p[0]}" cy="${p[1]}" r="${f.type==='outlet'?4:8}" fill="${f.type==='window'?'#69b2c5':'#f0a958'}" stroke="#fff" stroke-width="2"/>`;});app.plan.items.forEach(o=>{const sp=itemSpec(o),p=coords(o.x,o.z);content+=`<g transform="translate(${p[0]},${p[1]}) rotate(${o.r})"><rect x="${-sp.w*s/2}" y="${-sp.d*s/2}" width="${sp.w*s}" height="${sp.d*s}" rx="3" fill="${sp.color}" stroke="#25352f" stroke-width="1"/><text x="0" y="4" text-anchor="middle" fill="#101e19" font-family="sans-serif" font-size="10">${xmlEscape(o.type)}</text></g>`;});content+='</svg>';download('home-plan-floor-plan.svg',content,'image/svg+xml');say('Editable vector plan exported');}
function exportPNG(){if(!app.engine)return;app.engine.draw(true);const c=stage.querySelector('canvas');if(!c)return say('Viewport unavailable');try{const data=c.toDataURL('image/png'),a=document.createElement('a');a.href=data;a.download='home-plan-3d-view.png';a.click();say('3D view exported');}catch(e){say('Image export failed: '+e.message);}}
function savedNames(){try{return Object.keys(JSON.parse(localStorage.getItem('homeplan-variants-v2')||'{}')).slice(0,30);}catch{return []}}
function saveNamed(){const name=prompt('Name this arrangement:',app.plan.name)||'';if(!name.trim())return;try{const saves=JSON.parse(localStorage.getItem('homeplan-variants-v2')||'{}');saves[name.trim().slice(0,80)]=app.plan;localStorage.setItem('homeplan-variants-v2',JSON.stringify(saves));say('Saved '+name);updateInspector();}catch(e){say('Browser storage unavailable. Export JSON instead.');}}
