let modalReturnFocus=null;
function onModalKey(e){if($('modal').hidden)return;if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key!=='Tab')return;const focusable=[...$('modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(x=>x.getClientRects().length);if(!focusable.length){e.preventDefault();return;}const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&(document.activeElement===first||!$('modal').contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!$('modal').contains(document.activeElement))){e.preventDefault();first.focus();}}
function openModal(title,body){modalReturnFocus=document.activeElement;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modal').hidden=false;if(document.querySelector?.('.shell'))document.querySelector('.shell').inert=true;document.addEventListener('keydown',onModalKey,true);$('modalClose').focus();}
function closeModal(){if($('modal').hidden)return;$('modal').hidden=true;if(document.querySelector?.('.shell'))document.querySelector('.shell').inert=false;document.removeEventListener('keydown',onModalKey,true);const returnTo=modalReturnFocus;modalReturnFocus=null;try{const visible=returnTo?.getClientRects?.().length&&getComputedStyle(returnTo).visibility!=='hidden';(returnTo?.closest?.('#toolsPanel')?$('focusTools'):returnTo?.closest?.('#projectPanel')?$('focusProject'):(visible?returnTo:$('focusTools')))?.focus({preventScroll:true});}catch{}}
function openInspector(){$('inspector').classList.add('mobile-open');$('closeInspector').classList.remove('hidden');window.HomePlanFocus?.sync?.();}
